import {roleFor,ROLES} from './roles.mjs';
import {DEFAULT_COLOR,validColor,colorFor,colorName} from './colors.mjs';
import {createRun,step,applyInput} from './dungeon.mjs';
import {gameView} from './game.mjs';
import {directory} from './directory.mjs';
const $=id=>document.getElementById(id), prefix='next-game-v01-';
let peer=null,connection=null,links=new Map(),state=null,host=false,code='',busy=false,attempt=0;
const me=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
let simTimer=null,finishTimer=null,ending=false;
const view=gameView({canvas:$('dungeon'),me,onInput:m=>{if(host&&state?.run)applyInput(state.run,me,m);else send(connection,m)}});
const clean=v=>typeof v==='string'?v.replace(/[<>\x00-\x1f]/g,'').trim().slice(0,20):'';
const name=()=>clean($('name').value);
let selectedColor=validColor(sessionStorage.getItem('next-game-color'))?sessionStorage.getItem('next-game-color'):DEFAULT_COLOR;
function colorSelectors(){ $('roomcolor').value=selectedColor }
function changeColor(value){if(!validColor(value)||state?.phase==='playing')return;if(state?.players.some(p=>p.id!==me&&p.color===value)){error('That role is already taken. Choose another.');colorSelectors();return}selectedColor=value;sessionStorage.setItem('next-game-color',value);colorSelectors();if(state&&host){const player=state.players.find(p=>p.id===me);if(player){player.color=value;sync()}}else if(state)send(connection,{type:'color',color:value})}
$('roomcolor').onchange=e=>changeColor(e.target.value);colorSelectors();
function error(s){$('error').textContent=s}
function screen(id){for(const x of ['home','browser','room','game'])$(x).hidden=x!==id;error('')}
function requireName(){if(name())return true;error('Set your name before joining a lobby.');$('name').focus();return false}
function controls(on){busy=on;$('create').disabled=$('join').disabled=on;for(const b of $('roomlist').querySelectorAll('button'))b.disabled=on}
function send(c,m){if(c?.open)try{c.send(m)}catch{}}
function render(){if(!state)return;if(state.phase==='playing'){screen('game');document.body.classList.add('in-game');view.set(state.run);return}screen('room');$('start').disabled=!host;$('start').textContent=host?'Start Game':'Waiting for host';$('name').disabled=true;$('roomtitle').textContent=state.players[0].name+'’s lobby';$('roomcode').textContent=code;$('roomvisibility').textContent=state.visibility==='public'?'Public lobby':'Private lobby';$('players').replaceChildren();for(const p of state.players){const el=document.createElement('div');el.className='seat';const b=document.createElement('b');b.textContent=p.name+(p.id===me?' (you)':'');const small=document.createElement('small'),swatch=document.createElement('span');swatch.className='color-swatch';swatch.style.backgroundColor=colorFor(p.color);swatch.setAttribute('aria-hidden','true');small.textContent=(p.id===state.players[0].id?'Host':'Connected')+' · '+roleFor(p.color).name+' · '+colorName(p.color);el.append(swatch,b,small);$('players').append(el)}$('network').textContent=`${state.players.length}/8 players · Connected`;}
function sync(){for(const c of links.values())send(c,{type:'state',state});render();refreshDirectory()}
function reset(message='Ready when you are.'){attempt++;clearInterval(simTimer);clearTimeout(finishTimer);simTimer=finishTimer=null;view.stop();ending=false;$('ending').hidden=true;document.body.classList.remove('in-game');state=null;connection?.close();for(const c of links.values())c.close();links.clear();peer?.destroy();peer=connection=null;state=null;host=false;code='';controls(false);$('name').disabled=false;screen('browser');$('network').textContent=message;refreshDirectory()}
function attach(c){let player=null;const timeout=setTimeout(()=>{if(!player)c.close()},8000);c.on('data',m=>{if(player&&m?.type==='color'&&state?.phase==='lobby'&&validColor(m.color)){if(!state.players.some(p=>p.id!==player.id&&p.color===m.color))player.color=m.color;sync();return}if(player&&m?.type==='input'&&state?.run){applyInput(state.run,player.id,m);return}if(m?.type!=='join'||player)return;if(state?.phase==='playing'||ending){send(c,{type:'reject',message:'This run has already started. Create or join another lobby.'});return}const n=clean(m.name);if(!n||typeof m.id!=='string'||state.players.length>=8||state.players.some(p=>p.id===m.id)){send(c,{type:'reject',message:'This lobby is full or the player name is invalid.'});return}const available=Object.keys(ROLES).filter(color=>!state.players.some(p=>p.color===color));if(!available.length){send(c,{type:'reject',message:'All roles are taken.'});return}const chosen=validColor(m.color)&&available.includes(m.color)?m.color:available[0];player={id:m.id,name:n,color:chosen};links.set(c.peer,c);state.players.push(player);clearTimeout(timeout);sync()});c.on('close',()=>{clearTimeout(timeout);if(!player||!state||ending)return;if(state.phase==='playing'){finish('Run ended','A player disconnected. The lobby is closed; create a new one to play again.');return}links.delete(c.peer);state.players=state.players.filter(p=>p.id!==player.id);sync()});c.on('error',()=>c.close())}
function boot(isHost,requested){if(busy||state||!requireName())return;if(typeof Peer==='undefined'){error('Connection service could not load. Check your connection and reload.');return}const next=isHost?String(crypto.getRandomValues(new Uint32Array(1))[0]%1000000).padStart(6,'0'):requested;if(!/^\d{6}$/.test(next||'')){error('Enter a six-digit room code.');return}controls(true);error('');host=isHost;code=next;const run=++attempt;$('network').textContent='Connecting…';peer=new Peer(isHost?prefix+code:undefined,{debug:0});const timer=setTimeout(()=>{if(run===attempt&&!state){reset();error('Could not connect to that lobby. Check the code and try again.')}},12000);peer.on('open',()=>{if(run!==attempt)return;if(host){clearTimeout(timer);controls(false);state={visibility:$('visibility').value,phase:'lobby',players:[{id:me,name:name(),color:selectedColor}]};sync()}else{connection=peer.connect(prefix+code,{reliable:true,serialization:'json'});connection.on('open',()=>send(connection,{type:'join',id:me,name:name(),color:selectedColor}));connection.on('data',m=>{if(run!==attempt)return;if(m?.type==='ended'){finish(m.title,m.message,false);return}if(ending)return;if(m?.type==='state'&&Array.isArray(m.state?.players)&&m.state.players.some(p=>p.id===me)){clearTimeout(timer);controls(false);state=m.state;selectedColor=state.players.find(p=>p.id===me).color;colorSelectors();render()}else if(m?.type==='reject'){clearTimeout(timer);reset();error(m.message)}});connection.on('close',()=>{if(run===attempt&&!ending){clearTimeout(timer);reset('The host closed or disconnected from the lobby.')}});connection.on('error',()=>{if(run===attempt){clearTimeout(timer);reset();error('Connection failed. Try joining again.')}})}});peer.on('connection',c=>host&&state?attach(c):c.close());peer.on('error',e=>{if(run!==attempt)return;clearTimeout(timer);reset();error(e.type==='unavailable-id'?'That room code is already in use. Create a lobby again.':'Connection failed. Check the code, network access, and that the host is online.')});peer.on('disconnected',()=>{if(peer&&!peer.destroyed)peer.reconnect()})}
$('name').value=sessionStorage.getItem('next-game-name')||'';
function updateName(){$('play').disabled=!name();$('namehint').textContent=name()?'You’re ready. Find your next lobby.':'Enter your name in the top-right corner to play.';sessionStorage.setItem('next-game-name',name())}
$('name').oninput=updateName;updateName();$('play').onclick=()=>{if(requireName())screen('browser')};$('back').onclick=()=>screen('home');$('create').onclick=()=>boot(true);$('join').onclick=()=>boot(false,$('code').value.trim());$('code').oninput=()=>{$('code').value=$('code').value.replace(/\D/g,'')};$('code').onkeydown=e=>{if(e.key==='Enter')$('join').click()};$('leave').onclick=()=>reset();$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);$('copy').textContent='Copied';setTimeout(()=>$('copy').textContent='Copy code',1800)}catch{error('Your room code is '+code)}};
function finish(title,message,broadcast=true){if(ending)return;ending=true;clearInterval(simTimer);simTimer=null;if(host&&broadcast)for(const c of links.values())send(c,{type:'ended',title,message});$('endingtitle').textContent=title;$('endingtext').textContent=message+' Returning to the lobby browser…';$('ending').hidden=false;refreshDirectory();finishTimer=setTimeout(()=>reset(message),4500)}
$('start').onclick=()=>{if(!host||!state||state.phase!=='lobby'||ending)return;try{state.run=createRun(state.players);state.phase='playing';sync();$('dungeon').focus();let previous=performance.now(),accumulator=0,broadcastTicks=0;simTimer=setInterval(()=>{if(!state?.run||ending)return;const now=performance.now();accumulator+=Math.min((now-previous)/1000,.1);previous=now;while(accumulator>=1/60){if(step(state.run,1/60)){finish('Dungeon complete!','Everyone reached the goal. This lobby is now closed.');return}if(state.run.failed){finish('Run ended','All players have fallen. This lobby is now closed.');return}accumulator-=1/60}view.set(structuredClone(state.run));if(++broadcastTicks%5===0)for(const c of links.values())send(c,{type:'state',state})},1000/60)}catch(e){error(e.message)}};
$('exitrun').onclick=()=>{if(host)finish('Run ended','The host left the run. This lobby is now closed.');else reset('You left the run. Join or create a new lobby.')};
const refreshDirectory=directory({advertisement:()=>host&&state?.phase==='lobby'&&!ending&&state?.visibility==='public'?{code,name:state.players[0].name+'’s lobby',count:state.players.length}:null,onStatus:s=>$('directory-status').textContent=s.replaceAll('tables','lobbies').replaceAll('table','lobby'),onRooms:rooms=>{$('roomlist').replaceChildren();if(!rooms.length){const p=document.createElement('p');p.className='small';p.textContent='No public lobbies yet. Create one or join with a code.';$('roomlist').append(p)}for(const r of rooms){const el=document.createElement('div');el.className='publicroom';const detail=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small'),join=document.createElement('button');b.textContent=r.name;small.textContent=`${r.code} · ${r.count}/8 players`;detail.append(b,small);join.textContent='Join lobby';join.disabled=busy;join.onclick=()=>boot(false,r.code);el.append(detail,join);$('roomlist').append(el)}}});$('refresh').onclick=()=>refreshDirectory();
addEventListener('pagehide',()=>peer?.destroy());
